import { useState } from 'react';
import styles from './InvestmentForm.module.css';

const InvestmentForm = ({ onAddInvestment }) => {
  const [formData, setFormData] = useState({
    brand: '',
    processor: '',
    generation: '',
    initialCost: '',
    salePrice: '',
  });

  // Opciones de marcas predefinidas
  const brands = [
    'Lenovo',
    'HP',
    'Acer',
    'Fujitsu',
    'Dell',
    'MSI',
    'Asus',
    'Gateway',
    'Lenovo ThinkPad',
  ];

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const profit = formData.salePrice - formData.initialCost;
    onAddInvestment({ ...formData, profit });
    setFormData({
      brand: '',
      processor: '',
      generation: '',
      initialCost: '',
      salePrice: '',
    });
  };

  return (
    <form className={styles.form} onSubmit={handleSubmit}>
      <h2>Registrar Inversión en Laptop</h2>

      {/* Campo de selección para la marca */}
      <select
        name="brand"
        value={formData.brand}
        onChange={handleChange}
        required
      >
        <option value="" disabled>
          Selecciona una marca
        </option>
        {brands.map((brand, index) => (
          <option key={index} value={brand}>
            {brand}
          </option>
        ))}
      </select>

      <input
        type="text"
        name="processor"
        placeholder="Tipo de Procesador"
        value={formData.processor}
        onChange={handleChange}
        required
      />
      <input
        type="text"
        name="generation"
        placeholder="Generación"
        value={formData.generation}
        onChange={handleChange}
        required
      />
      <input
        type="number"
        name="initialCost"
        placeholder="Costo Inicial"
        value={formData.initialCost}
        onChange={handleChange}
        required
      />
      <input
        type="number"
        name="salePrice"
        placeholder="Precio de Venta"
        value={formData.salePrice}
        onChange={handleChange}
        required
      />
      <button type="submit">Agregar Inversión</button>
    </form>
  );
};

export default InvestmentForm;
